variables.ids:
{%- set e = sd.get('entity_id', []) -%}
{%- set e = ([e] if e is string else (e | list)) -%}
{%- set a = sd.get('area_id', []) -%}
{%- set a = ([a] if a is string else (a | list)) -%}
{%- set ns = namespace(l=e) -%}
{%- for x in a -%}{%- set ns.l = ns.l + (area_entities(x) | select('match', 'light\.') | list) -%}{%- endfor -%}
{#- Match at bulb level: break the changed entities and each scheduled lamp down to bulbs (HA groups via expand, Zigbee2MQTT groups via group_entities); a scheduled lamp sharing any bulb with the change gets the hold. -#}
{%- set b = namespace(l=[]) -%}
{%- for x in ns.l + (expand(ns.l) | map(attribute='entity_id') | list) -%}{%- set b.l = b.l + [x] + (state_attr(x, 'group_entities') or []) | list -%}{%- endfor -%}
{%- set out = namespace(r=[]) -%}
{%- for s in scheduled -%}{%- if ([s] + (state_attr(s, 'group_entities') or []) | list) | select('in', b.l) | list | count > 0 -%}{%- set out.r = out.r + [s] -%}{%- endif -%}{%- endfor -%}
{{ out.r }}
